(()=>{let i=self;i.addEventListener("push",t=>{let n=t.data?.json()??{};t.waitUntil(i.registration.showNotification(n.title??"DE GEMEENSCHAP",{body:n.body??"Nieuw bericht",icon:n.icon??"/icon-192",badge:"/icon-192",data:{url:n.url??"/activities"}}))}),i.addEventListener("notificationclick",t=>{t.notification.close();let n=t.notification.data.url??"/activities";t.waitUntil(i.clients.matchAll({type:"window",includeUncontrolled:!0}).then(t=>{let e=t.find(i=>i.url===n);return e?e.focus():i.clients.openWindow(n)}))})})();